import java.util.*;class RiverIslandTest{public static void main(String[]a){int n=256;var w=new TerraForge.World(n,62,83);Arrays.fill(w.height,92);var e=w.environment;e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];e.snow=new float[n*n];e.resolvedRiverChannels=true;for(int z=122;z<=134;z++)for(int x=20;x<236;x++){int i=z*n+x;e.water[i]=90;e.height[i]=86;e.river[i]=1;}RiverRibbon.island(w,0,0,62,new RiverRibbon.SedimentIsland(128,128,20,2,0));var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("courses",1.0);e=RiverBanks.apply(node,e,n,n,62,83,0,0,()->false);if(e.waterY(128*n+128,62)>Math.round(e.height[128*n+128]))throw new AssertionError("Island disappeared");for(int z:new int[]{124,132})for(int x=99;x<=157;x++)if(e.waterY(z*n+x,62)<=Math.round(e.height[z*n+x]))throw new AssertionError("Side channel blocked");for(int x:new int[]{99,157})if(e.waterY(128*n+x,62)<=Math.round(e.height[128*n+x]))throw new AssertionError("Branches do not split and rejoin");System.out.println("PASS: sediment island splits a wet channel into two connected arms that rejoin; survives bank processing");}}
